import{_ as i,o as a,c as n,a2 as t}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Architecture Migration Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/migration-decisions.md","filePath":"architecture/migration-decisions.md","lastUpdated":null}'),o={name:"architecture/migration-decisions.md"};function s(r,e,l,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture-migration-decisions" tabindex="-1">Architecture Migration Decisions <a class="header-anchor" href="#architecture-migration-decisions" aria-label="Permalink to &quot;Architecture Migration Decisions&quot;">​</a></h1><p><strong>Status:</strong> Active migration inventory<br><strong>Date:</strong> 2026-07-28<br><strong>Beads issue:</strong> <code>archie-core-5d7</code></p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document records what remains to be decided before Archie&#39;s current implementation can be migrated into the approved domain-oriented structure.</p><p>The product and core domain model are not being redesigned. Existing Archie behaviour and the existing session implementation are the migration baseline. Remaining decisions MUST be grounded in current packages, consumers, tests, persistence, and runtime wiring.</p><h2 id="confirmed-domain-packages" tabindex="-1">Confirmed domain packages <a class="header-anchor" href="#confirmed-domain-packages" aria-label="Permalink to &quot;Confirmed domain packages&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>internal/domain/</span></span>
<span class="line"><span>  identity/</span></span>
<span class="line"><span>  agent/</span></span>
<span class="line"><span>  workflow/</span></span>
<span class="line"><span>  messaging/</span></span>
<span class="line"><span>  workintake/</span></span>
<span class="line"><span>  plugin/</span></span></code></pre></div><ul><li><code>identity</code> owns persistent actors, lifecycle, ownership, attribution, and audit identity.</li><li><code>agent</code> owns persistent assistants, specialisation, instructions, model-independent continuity, capability context, and associations with identity and memory.</li><li><code>workflow</code> is a separate domain. It owns reusable, versioned Workflow definitions, WorkflowSteps, WorkflowExecutions, StepExecutions, Attempts, outcomes, and typed Workflow plugin contracts.</li><li><code>messaging</code> owns canonical Messages, Conversations, branches, channel and source correlation, replies, acknowledgements, delivery attempts, events, and projections.</li><li><code>workintake</code> owns admission, validation, deterministic routing, and accepted work requests for the optional transition into durable workflow-backed execution.</li><li><code>plugin</code> owns generic plugin identity, discovery, compatibility, and lifecycle mechanics. It remains metadata-only; capability semantics and typed registration belong to the owning domain.</li></ul><p>Memory&#39;s final package placement remains undecided pending focused review of the existing implementation.</p><p>The following are approved shared or composition packages, not domains:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>internal/eventbus/</span></span>
<span class="line"><span>internal/policy/</span></span>
<span class="line"><span>internal/infrastructure/</span></span>
<span class="line"><span>internal/app/archied/</span></span>
<span class="line"><span>internal/app/agentworker/</span></span></code></pre></div><h2 id="remaining-migration-decisions" tabindex="-1">Remaining migration decisions <a class="header-anchor" href="#remaining-migration-decisions" aria-label="Permalink to &quot;Remaining migration decisions&quot;">​</a></h2><h3 id="_1-complete-package-destination-map" tabindex="-1">1. Complete package destination map <a class="header-anchor" href="#_1-complete-package-destination-map" aria-label="Permalink to &quot;1. Complete package destination map&quot;">​</a></h3><p>Every current package MUST receive one explicit disposition:</p><ul><li>move into a confirmed domain;</li><li>move under infrastructure as an implementation of a domain-owned contract;</li><li>move into application composition;</li><li>merge with an identified duplicate;</li><li>remain as an approved shared application contract;</li><li>move to a plugin, extra, deployment, example, or generated artifact;</li><li>be deleted after its replacement is proven.</li></ul><p>The largest unreviewed areas include memory, tools and capabilities, workspace and worktree behaviour, gates, storage, events, web UI, containers, RPC packages, release management, and scheduling.</p><p>The destination matrix MUST name the behaviour owner, target path, dependencies to remove, state and contracts to preserve, migration prerequisites, and deletion criteria.</p><h3 id="_2-session-and-messaging-migration" tabindex="-1">2. Session and Messaging migration <a class="header-anchor" href="#_2-session-and-messaging-migration" aria-label="Permalink to &quot;2. Session and Messaging migration&quot;">​</a></h3><p>The existing session implementation is the migration baseline. The migration must decide:</p><ul><li>which session and message components are retained or adapted;</li><li>how Agent, user, channel, Conversation, and branch ownership are added;</li><li>how Archie&#39;s parallel gateway session implementation is replaced;</li><li>how canonical Messages become immutable persisted records;</li><li>how existing NellDB sessions and messages are migrated;</li><li>how outbound delivery, retry, acknowledgement, deduplication, and failure semantics are represented;</li><li>how current Telegram, email, webhook, forge, and Jira integrations migrate to Messaging infrastructure adapters.</li></ul><p>The following are already decided and MUST NOT be reopened without contradictory implementation evidence:</p><ul><li>the composite Conversation identity;</li><li>immutable MessageIDs;</li><li>typed tool-call and tool-result messages;</li><li>exact branch lineage through ParentConversationID and ForkMessageID;</li><li>parent and child transcript isolation;</li><li>normal scoped-memory behaviour regardless of the originating Conversation;</li><li>Messaging and Work Intake ownership.</li></ul><h3 id="_3-identity-data-migration" tabindex="-1">3. Identity data migration <a class="header-anchor" href="#_3-identity-data-migration" aria-label="Permalink to &quot;3. Identity data migration&quot;">​</a></h3><p>The migration must define:</p><ul><li>the durable identity schema and repository implementation;</li><li>bootstrap of the permanent system identity;</li><li>stable IdentityIDs for existing configured Agents;</li><li>migration from configured identity names, empty-string ownership, and bot usernames;</li><li>preservation of historical attribution;</li><li>identity-aware uniqueness and transport deduplication;</li><li>correction of container and RPC capability resolution so execution uses the owning identity&#39;s bindings;</li><li>removal of identity-string equality from access-control behaviour.</li></ul><p>Exact schema and method signatures are implementation decisions. The approved Identity lifecycle and attribution semantics are fixed migration constraints.</p><h3 id="_4-workflow-migration" tabindex="-1">4. Workflow migration <a class="header-anchor" href="#_4-workflow-migration" aria-label="Permalink to &quot;4. Workflow migration&quot;">​</a></h3><p>The current implementation must be transformed deliberately:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>store.Task            -&gt; WorkflowExecution</span></span>
<span class="line"><span>mutable Stage         -&gt; StepExecution history</span></span>
<span class="line"><span>RetryCount / Attempt  -&gt; Attempt records</span></span>
<span class="line"><span>workflow.Registry     -&gt; versioned Workflow definitions</span></span>
<span class="line"><span>current stages        -&gt; WorkflowStep definitions or Workflow plugins</span></span></code></pre></div><p>The migration must decide:</p><ul><li>Workflow definition and version persistence;</li><li>the smallest accepted-work-request contract consumed from Work Intake;</li><li>the enforced WorkflowExecution state machine;</li><li>atomic state and domain-event persistence;</li><li>migration of existing task rows and transition history;</li><li>disposition of current skill, Yaegi, and stage-plugin implementations;</li><li>the versioned worker-handoff contract;</li><li>scheduler, claim, retry, crash-recovery, and waiting-human cutover.</li></ul><p>Workflow remains a separate domain from Agent. A user or Agent may define or invoke a Workflow, but Workflow semantics and plugins remain Workflow-owned.</p><h3 id="_5-memory-placement-and-storage" tabindex="-1">5. Memory placement and storage <a class="header-anchor" href="#_5-memory-placement-and-storage" aria-label="Permalink to &quot;5. Memory placement and storage&quot;">​</a></h3><p>The four required scopes are fixed:</p><ul><li>global shared;</li><li>Agent-wide;</li><li>user-wide;</li><li>Agent-user relationship.</li></ul><p>A focused review of <code>internal/memory</code>, its providers, consumers, persistence, and tests must decide:</p><ul><li><code>internal/domain/memory</code> versus ownership within the Agent domain;</li><li>the authoritative memory record and revision model;</li><li>provider and infrastructure boundaries;</li><li>retrieval and access enforcement;</li><li>migration of existing memory data;</li><li>provenance representation.</li></ul><p>Conversation branches do not create another memory scope. A memory action has the same scoped effect regardless of which Conversation originated it.</p><h3 id="_6-runtime-and-process-boundaries" tabindex="-1">6. Runtime and process boundaries <a class="header-anchor" href="#_6-runtime-and-process-boundaries" aria-label="Permalink to &quot;6. Runtime and process boundaries&quot;">​</a></h3><p>The migration must decide which current execution paths survive:</p><ul><li>in-process execution;</li><li><code>archie-agent</code> subprocess execution;</li><li>NATS worker execution;</li><li>container isolation;</li><li>forge, store, and worktree RPC services.</li></ul><p>The source architecture remains a modular monolith. A retained process boundary requires a concrete security-isolation, failure-containment, scaling, or operational justification. Possible future extraction is insufficient.</p><h3 id="_7-shared-mechanics" tabindex="-1">7. Shared mechanics <a class="header-anchor" href="#_7-shared-mechanics" aria-label="Permalink to &quot;7. Shared mechanics&quot;">​</a></h3><p>The following cross-domain mechanics require exact contracts before dependent packages migrate:</p><ul><li>event-bus delivery and failure semantics;</li><li>policy evaluation API, composition, and precedence;</li><li>configuration candidate preparation, health validation, atomic promotion, observation, and rollback;</li><li>service-specific health, bounded remediation, isolation, and escalation;</li><li>changelog association and grouping.</li></ul><p>These shared mechanisms do not acquire ownership of domain meaning. Domains continue to own their commands, events, policies, settings, and consequences.</p><p>The copied Go <code>specgen</code> and VitePress documentation pipeline, output placement, developer commands, drift checking, hook sequence, and CI sequence are defined in <code>generated-documentation.md</code>. Adapting the copied files, implementing Archie&#39;s normalized documentation model and page renderers, and cutting <code>docs</code> over to its final location remain migration work rather than open product architecture.</p><h3 id="_8-cutover-sequence" tabindex="-1">8. Cutover sequence <a class="header-anchor" href="#_8-cutover-sequence" aria-label="Permalink to &quot;8. Cutover sequence&quot;">​</a></h3><p>The final migration plan must order:</p><ul><li>compatibility adapters;</li><li>schema migrations and data backfills;</li><li>any required dual-read or transitional paths;</li><li>domain-by-domain package replacement;</li><li>production wiring changes;</li><li>legacy package removal;</li><li>architecture tests preventing dependency regression;</li><li>focused, integration, race, and full quality gates.</li></ul><p>Each legacy package requires objective removal criteria. No compatibility path may become an indefinite second implementation.</p><h2 id="completion-criteria" tabindex="-1">Completion criteria <a class="header-anchor" href="#completion-criteria" aria-label="Permalink to &quot;Completion criteria&quot;">​</a></h2><p>Migration design is complete when:</p><ul><li>every current package has one approved owner and destination;</li><li>every mutable record has one authoritative owner and migration path;</li><li>all external and cross-process contracts have versioned owners;</li><li>existing behaviour and data have explicit parity requirements;</li><li>process boundaries have evidence-backed justification;</li><li>the cutover order preserves a working application;</li><li>legacy deletion criteria and deterministic architecture tests are defined;</li><li>no unresolved decision requires an implementer to invent domain semantics.</li></ul><p>Exact Go APIs, SQL statements, and mechanical refactoring steps MAY be finalized during implementation when they do not change these semantics.</p>`,55)])])}const h=i(o,[["render",s]]);export{u as __pageData,h as default};
